INSERT INTO curriculum_nodes (id, slug, phase_id, order_index, title, subtitle, cs_foundation, ai_convergence, xp_reward, level_required, position_x, position_y, handbook_markdown, starter_code, test_suite, defense_prompts) VALUES
('node-8-1', 'phase-08-lesson-01-the-4-step-system-design-interview-framew', 'module-9', 1, 'Lesson 9.1: The 4-Step System Design Interview Framework & Requirement Scoping', 'Prerequisites: Phase 4, Phase 7', 'Prerequisites: Phase 4, Phase 7 | Subtopics: 6 items', 'Systems project application', 260, 9, 2060.0, 50.0, '# Lesson 8.1: The 4-Step System Design Interview Framework & Requirement Scoping

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 4, Phase 7
- **Subtopics**:
  - `8.1.1` Step 1: Scoping functional requirements (core user journeys) vs non-functional requirements (latency, availability, scale)
  - `8.1.2` Defining out-of-scope boundaries to prevent architectural derailment during interview discussions
  - `8.1.3` Step 2: Back-of-the-envelope capacity estimation: QPS, bandwidth, storage, memory, and cache projections
  - `8.1.4` Step 3: High-Level Architecture (HLA): client, CDN, load balancer, API gateway, stateless services, cache, and database
  - `8.1.5` Step 4: Deep Dive & Bottlenecks: identifying single points of failure, partition tolerance, and failover workflows
  - `8.1.6` Collaborative communication: driving the discussion, active listening, asking clarifying questions, and managing time
- **Key Failure Modes & Edge Cases**: Jumping straight into database schemas or microservices without scoping functional and non-functional requirements.
- **Verification & Mastery Check**: Write a structured 1-page system requirements specification (SRS) for a global link shortening platform under 15 minutes.
- **Project Application**: System Design Portfolio: Requirement scoping templates.', '{"solution.py": "# Phase 8 // Lesson 8.1: The 4-Step System Design Interview Framework & Requirement Scoping\n\ndef solve():\n    \"\"\"\n    Verification: Write a structured 1-page system requirements specification (SRS) for a global link shortening platf\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "8.1", "subtopics_count": 6, "verification_criteria": "Write a structured 1-page system requirements specification (SRS) for a global link shortening platform under 15 minutes.", "subtopics": ["8.1.1 Step 1: Scoping functional requirements (core user journeys) vs non-functional requirements (latency, availability, scale)", "8.1.2 Defining out-of-scope boundaries to prevent architectural derailment during interview discussions", "8.1.3 Step 2: Back-of-the-envelope capacity estimation: QPS, bandwidth, storage, memory, and cache projections", "8.1.4 Step 3: High-Level Architecture (HLA): client, CDN, load balancer, API gateway, stateless services, cache, and database", "8.1.5 Step 4: Deep Dive & Bottlenecks: identifying single points of failure, partition tolerance, and failover workflows", "8.1.6 Collaborative communication: driving the discussion, active listening, asking clarifying questions, and managing time"]}'::jsonb, '["Explain how this implementation prevents: Jumping straight into database schemas or microservices without scoping functional and non-functional requirements.", "How does The 4-Step System Design Interview Framework & Requirement Scoping scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-8-2', 'phase-08-lesson-02-back-of-the-envelope-estimation-numbers-e', 'module-9', 2, 'Lesson 9.2: Back-of-the-Envelope Estimation: Numbers Every Engineer Must Know', 'Prerequisites: Phase 0, Lesson 8.1', 'Prerequisites: Phase 0, Lesson 8.1 | Subtopics: 6 items', 'Systems project application', 260, 9, 2120.0, 100.0, '# Lesson 8.2: Back-of-the-Envelope Estimation: Numbers Every Engineer Must Know

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 0, Lesson 8.1
- **Subtopics**:
  - `8.2.1` Latency numbers to memorize: L1 cache (1ns), RAM (100ns), SSD read (100µs), HDD seek (10ms), cross-datacenter RTT (150ms)
  - `8.2.2` Throughput calculations: converting Monthly Active Users (MAU) and Daily Active Users (DAU) to Read/Write QPS
  - `8.2.3` Peak multiplier heuristics: average QPS vs peak QPS (typically $2\times$ to $5\times$ average load)
  - `8.2.4` Storage volumetric estimation: bytes per record $\times$ records per day $\times$ retention years $\times$ replication factor
  - `8.2.5` Bandwidth volumetric estimation: ingress bandwidth (write QPS $\times$ payload size) vs egress bandwidth (read QPS $\times$ payload size)
  - `8.2.6` Memory and cache sizing: 80/20 Pareto rule (20% of hot data generates 80% of read traffic) memory provisioning
- **Key Failure Modes & Edge Cases**: Confusing bits (Gbps) with bytes (GB/s); failing to account for peak load spikes leading to 50% infrastructure under-provisioning.
- **Verification & Mastery Check**: Calculate exact QPS, storage (5-year), RAM cache, and bandwidth requirements for Twitter (500M DAU) with zero calculator aids.
- **Project Application**: System Design Portfolio: Automated capacity planning spreadsheet.', '{"solution.py": "# Phase 8 // Lesson 8.2: Back-of-the-Envelope Estimation: Numbers Every Engineer Must Know\n\ndef solve():\n    \"\"\"\n    Verification: Calculate exact QPS, storage (5-year), RAM cache, and bandwidth requirements for Twitter (500M DAU) \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "8.2", "subtopics_count": 6, "verification_criteria": "Calculate exact QPS, storage (5-year), RAM cache, and bandwidth requirements for Twitter (500M DAU) with zero calculator aids.", "subtopics": ["8.2.1 Latency numbers to memorize: L1 cache (1ns), RAM (100ns), SSD read (100\u00b5s), HDD seek (10ms), cross-datacenter RTT (150ms)", "8.2.2 Throughput calculations: converting Monthly Active Users (MAU) and Daily Active Users (DAU) to Read/Write QPS", "8.2.3 Peak multiplier heuristics: average QPS vs peak QPS (typically $2\\times$ to $5\\times$ average load)", "8.2.4 Storage volumetric estimation: bytes per record $\\times$ records per day $\\times$ retention years $\\times$ replication factor", "8.2.5 Bandwidth volumetric estimation: ingress bandwidth (write QPS $\\times$ payload size) vs egress bandwidth (read QPS $\\times$ payload size)", "8.2.6 Memory and cache sizing: 80/20 Pareto rule (20% of hot data generates 80% of read traffic) memory provisioning"]}'::jsonb, '["Explain how this implementation prevents: Confusing bits (Gbps) with bytes (GB/s); failing to account for peak load spikes leading to 50% infrastructure under-pro", "How does Back-of-the-Envelope Estimation: Numbers Every Engineer Must Know scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-8-3', 'phase-08-lesson-03-data-storage-paradigms-database-selection', 'module-9', 3, 'Lesson 9.3: Data Storage Paradigms & Database Selection Matrix', 'Prerequisites: Phase 4, Phase 7', 'Prerequisites: Phase 4, Phase 7 | Subtopics: 6 items', 'Systems project application', 260, 9, 2000.0, 150.0, '# Lesson 8.3: Data Storage Paradigms & Database Selection Matrix

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 4, Phase 7
- **Subtopics**:
  - `8.3.1` Relational (RDBMS) vs NoSQL: ACID guarantees vs horizontal scalability, schema flexibility, and query patterns
  - `8.3.2` Document stores (MongoDB): nested denormalized hierarchical documents, index structures, and write-heavy workloads
  - `8.3.3` Wide-column stores (Cassandra, ScyllaDB): log-structured merge trees (LSM), tunable consistency, high write throughput
  - `8.3.4` Key-Value stores (Redis, DynamoDB): lightning sub-millisecond lookups, TTL expirations, and partition keys
  - `8.3.5` Graph databases (Neo4j): vertex and edge traversal, index-free adjacency, and social graph fraud detection
  - `8.3.6` Time-series databases (InfluxDB, TimescaleDB): columnar compression, downsampling, and high-frequency sensor/metric ingestion
- **Key Failure Modes & Edge Cases**: Choosing NoSQL for financial balances without transactional multi-record atomicity; choosing RDBMS for petabyte append-only logs.
- **Verification & Mastery Check**: Draft a comprehensive technical decision matrix comparing PostgreSQL, Cassandra, DynamoDB, and Redis across 8 operational criteria.
- **Project Application**: System Design Portfolio: Database architectural selection guide.', '{"solution.py": "# Phase 8 // Lesson 8.3: Data Storage Paradigms & Database Selection Matrix\n\ndef solve():\n    \"\"\"\n    Verification: Draft a comprehensive technical decision matrix comparing PostgreSQL, Cassandra, DynamoDB, and Redis\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "8.3", "subtopics_count": 6, "verification_criteria": "Draft a comprehensive technical decision matrix comparing PostgreSQL, Cassandra, DynamoDB, and Redis across 8 operational criteria.", "subtopics": ["8.3.1 Relational (RDBMS) vs NoSQL: ACID guarantees vs horizontal scalability, schema flexibility, and query patterns", "8.3.2 Document stores (MongoDB): nested denormalized hierarchical documents, index structures, and write-heavy workloads", "8.3.3 Wide-column stores (Cassandra, ScyllaDB): log-structured merge trees (LSM), tunable consistency, high write throughput", "8.3.4 Key-Value stores (Redis, DynamoDB): lightning sub-millisecond lookups, TTL expirations, and partition keys", "8.3.5 Graph databases (Neo4j): vertex and edge traversal, index-free adjacency, and social graph fraud detection", "8.3.6 Time-series databases (InfluxDB, TimescaleDB): columnar compression, downsampling, and high-frequency sensor/metric ingestion"]}'::jsonb, '["Explain how this implementation prevents: Choosing NoSQL for financial balances without transactional multi-record atomicity; choosing RDBMS for petabyte append-o", "How does Data Storage Paradigms & Database Selection Matrix scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-8-4', 'phase-08-lesson-04-caching-architectures-invalidation-thunde', 'module-9', 4, 'Lesson 9.4: Caching Architectures: Invalidation, Thundering Herd & Topologies', 'Prerequisites: Phase 4, Lesson 8.2', 'Prerequisites: Phase 4, Lesson 8.2 | Subtopics: 6 items', 'Systems project application', 260, 9, 2060.0, 200.0, '# Lesson 8.4: Caching Architectures: Invalidation, Thundering Herd & Topologies

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 4, Lesson 8.2
- **Subtopics**:
  - `8.4.1` Caching topologies: In-memory local cache vs Distributed cache clusters (Redis, Memcached) vs Multi-tier caching
  - `8.4.2` Cache access patterns: Cache-Aside (Lazy Loading), Read-Through, Write-Through, and Write-Behind (Write-Back)
  - `8.4.3` Cache eviction policies: Least Recently Used (LRU), Least Frequently Used (LFU), First In First Out (FIFO)
  - `8.4.4` Cache Invalidation problems: cache stampede / thundering herd mitigation using mutex locking, probabilistic early expiration (XFetch)
  - `8.4.5` Cache Penetration (queries for non-existent keys): mitigating via null caching and Bloom filters
  - `8.4.6` Cache Breakdown (hot key expiry) and Cache Avalanche (simultaneous massive key expirations) mitigation with TTL jitter
- **Key Failure Modes & Edge Cases**: Cache avalanche crashing core databases when 100,000 keys expire at midnight simultaneously without randomized TTL jitter.
- **Verification & Mastery Check**: Implement the XFetch probabilistic early cache expiration algorithm in Python; simulate high-concurrency read traffic under load.
- **Project Application**: System Design Portfolio: High-throughput caching architectural patterns.', '{"solution.py": "# Phase 8 // Lesson 8.4: Caching Architectures: Invalidation, Thundering Herd & Topologies\n\ndef solve():\n    \"\"\"\n    Verification: Implement the XFetch probabilistic early cache expiration algorithm in Python; simulate high-concurr\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "8.4", "subtopics_count": 6, "verification_criteria": "Implement the XFetch probabilistic early cache expiration algorithm in Python; simulate high-concurrency read traffic under load.", "subtopics": ["8.4.1 Caching topologies: In-memory local cache vs Distributed cache clusters (Redis, Memcached) vs Multi-tier caching", "8.4.2 Cache access patterns: Cache-Aside (Lazy Loading), Read-Through, Write-Through, and Write-Behind (Write-Back)", "8.4.3 Cache eviction policies: Least Recently Used (LRU), Least Frequently Used (LFU), First In First Out (FIFO)", "8.4.4 Cache Invalidation problems: cache stampede / thundering herd mitigation using mutex locking, probabilistic early expiration (XFetch)", "8.4.5 Cache Penetration (queries for non-existent keys): mitigating via null caching and Bloom filters", "8.4.6 Cache Breakdown (hot key expiry) and Cache Avalanche (simultaneous massive key expirations) mitigation with TTL jitter"]}'::jsonb, '["Explain how this implementation prevents: Cache avalanche crashing core databases when 100,000 keys expire at midnight simultaneously without randomized TTL jitte", "How does Caching Architectures: Invalidation, Thundering Herd & Topologies scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-8-5', 'phase-08-lesson-05-load-balancing-reverse-proxies-anycast-ro', 'module-9', 5, 'Lesson 9.5: Load Balancing, Reverse Proxies & Anycast Routing', 'Prerequisites: Phase 4, Phase 7', 'Prerequisites: Phase 4, Phase 7 | Subtopics: 6 items', 'Systems project application', 260, 9, 2120.0, 250.0, '# Lesson 8.5: Load Balancing, Reverse Proxies & Anycast Routing

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 4, Phase 7
- **Subtopics**:
  - `8.5.1` Layer 4 (Transport, TCP/UDP) vs Layer 7 (Application, HTTP/gRPC) load balancing trade-offs and SSL termination
  - `8.5.2` Load balancing algorithms: Round Robin, Weighted Least Connections, IP Hash, and Consistent Hashing
  - `8.5.3` Anycast BGP routing: announcing the same IP address globally to route client traffic to the nearest topological datacenter
  - `8.5.4` Reverse proxy mechanics: NGINX and Envoy proxy internals, connection pooling, buffer management, and gzip/brotli compression
  - `8.5.5` Direct Server Return (DSR): high-throughput video streaming optimization bypassing load balancers for egress traffic
  - `8.5.6` High-availability load balancers: Active-Passive configurations using VRRP (Virtual Router Redundancy Protocol) and Keepalived
- **Key Failure Modes & Edge Cases**: Layer 7 load balancer becoming CPU-bound due to un-offloaded TLS handshakes without dedicated cryptographic hardware.
- **Verification & Mastery Check**: Configure an Envoy proxy topology demonstrating Layer 7 content-based routing, weighted canary traffic splitting, and circuit breaking.
- **Project Application**: System Design Portfolio: Global edge routing and load balancing blueprints.', '{"solution.py": "# Phase 8 // Lesson 8.5: Load Balancing, Reverse Proxies & Anycast Routing\n\ndef solve():\n    \"\"\"\n    Verification: Configure an Envoy proxy topology demonstrating Layer 7 content-based routing, weighted canary traff\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "8.5", "subtopics_count": 6, "verification_criteria": "Configure an Envoy proxy topology demonstrating Layer 7 content-based routing, weighted canary traffic splitting, and circuit breaking.", "subtopics": ["8.5.1 Layer 4 (Transport, TCP/UDP) vs Layer 7 (Application, HTTP/gRPC) load balancing trade-offs and SSL termination", "8.5.2 Load balancing algorithms: Round Robin, Weighted Least Connections, IP Hash, and Consistent Hashing", "8.5.3 Anycast BGP routing: announcing the same IP address globally to route client traffic to the nearest topological datacenter", "8.5.4 Reverse proxy mechanics: NGINX and Envoy proxy internals, connection pooling, buffer management, and gzip/brotli compression", "8.5.5 Direct Server Return (DSR): high-throughput video streaming optimization bypassing load balancers for egress traffic", "8.5.6 High-availability load balancers: Active-Passive configurations using VRRP (Virtual Router Redundancy Protocol) and Keepalived"]}'::jsonb, '["Explain how this implementation prevents: Layer 7 load balancer becoming CPU-bound due to un-offloaded TLS handshakes without dedicated cryptographic hardware.", "How does Load Balancing, Reverse Proxies & Anycast Routing scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-8-6', 'phase-08-lesson-06-api-gateway-architectures-rate-limiting-a', 'module-9', 6, 'Lesson 9.6: API Gateway Architectures, Rate Limiting & Aggregation', 'Prerequisites: Phase 4, Lesson 8.5', 'Prerequisites: Phase 4, Lesson 8.5 | Subtopics: 6 items', 'Systems project application', 260, 9, 2000.0, 300.0, '# Lesson 8.6: API Gateway Architectures, Rate Limiting & Aggregation

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 4, Lesson 8.5
- **Subtopics**:
  - `8.6.1` API Gateway responsibilities: request routing, protocol translation (gRPC to JSON), authentication, and telemetry
  - `8.6.2` Backend-For-Frontend (BFF) pattern: tailored API gateways for mobile, web, and public developer clients
  - `8.6.3` Distributed Rate Limiting algorithms: Token Bucket, Leaky Bucket, Sliding Window Counter with Redis and Lua scripts
  - `8.6.4` Distributed rate limiting synchronization: centralized Redis vs local memory with gossip protocol synchronization
  - `8.6.5` Request aggregation and batching: combining multiple microservice calls into single client responses to reduce latency
  - `8.6.6` Security controls at the gateway: IP whitelisting, geo-blocking, DDoS mitigation, and WAF rule evaluation
- **Key Failure Modes & Edge Cases**: Centralized Redis rate limiter creating a single point of failure and adding 10ms latency overhead to every API request.
- **Verification & Mastery Check**: Implement a sliding window counter rate limiter in Redis Lua script handling 50,000 concurrent requests with zero race conditions.
- **Project Application**: System Design Portfolio: Enterprise API Gateway and rate limiting architecture.', '{"solution.py": "# Phase 8 // Lesson 8.6: API Gateway Architectures, Rate Limiting & Aggregation\n\ndef solve():\n    \"\"\"\n    Verification: Implement a sliding window counter rate limiter in Redis Lua script handling 50,000 concurrent reque\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "8.6", "subtopics_count": 6, "verification_criteria": "Implement a sliding window counter rate limiter in Redis Lua script handling 50,000 concurrent requests with zero race conditions.", "subtopics": ["8.6.1 API Gateway responsibilities: request routing, protocol translation (gRPC to JSON), authentication, and telemetry", "8.6.2 Backend-For-Frontend (BFF) pattern: tailored API gateways for mobile, web, and public developer clients", "8.6.3 Distributed Rate Limiting algorithms: Token Bucket, Leaky Bucket, Sliding Window Counter with Redis and Lua scripts", "8.6.4 Distributed rate limiting synchronization: centralized Redis vs local memory with gossip protocol synchronization", "8.6.5 Request aggregation and batching: combining multiple microservice calls into single client responses to reduce latency", "8.6.6 Security controls at the gateway: IP whitelisting, geo-blocking, DDoS mitigation, and WAF rule evaluation"]}'::jsonb, '["Explain how this implementation prevents: Centralized Redis rate limiter creating a single point of failure and adding 10ms latency overhead to every API request.", "How does API Gateway Architectures, Rate Limiting & Aggregation scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-8-7', 'phase-08-lesson-07-message-queues-vs-event-streams-decouplin', 'module-9', 7, 'Lesson 9.7: Message Queues vs Event Streams: Decoupling Asynchronous Systems', 'Prerequisites: Phase 4, Phase 7', 'Prerequisites: Phase 4, Phase 7 | Subtopics: 6 items', 'Systems project application', 260, 9, 2060.0, 350.0, '# Lesson 8.7: Message Queues vs Event Streams: Decoupling Asynchronous Systems

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 4, Phase 7
- **Subtopics**:
  - `8.7.1` Queue-based messaging (RabbitMQ, SQS): push model, message acknowledgment, individual message consumption, worker pools
  - `8.7.2` Log-based event streaming (Kafka, Kinesis): pull model, partitioned commit logs, ordered replayability, consumer groups
  - `8.7.3` Choosing between Queues and Streams: complex routing/task distribution vs high-throughput real-time event analytics
  - `8.7.4` Message delivery guarantees: At-most-once, At-least-once, Exactly-once processing (idempotent consumers)
  - `8.7.5` Dead Letter Queues (DLQ) and retry backoff strategies: handling poisoned messages without blocking queue pipelines
  - `8.7.6` Event-driven architecture patterns: Event Sourcing, Command Query Responsibility Segregation (CQRS), and Saga choreography
- **Key Failure Modes & Edge Cases**: Using a message queue as a permanent database without understanding broker storage limits and memory backpressure.
- **Verification & Mastery Check**: Design an end-to-end asynchronous order processing architecture comparing RabbitMQ task queues with Kafka event streaming.
- **Project Application**: System Design Portfolio: Asynchronous event messaging blueprints.', '{"solution.py": "# Phase 8 // Lesson 8.7: Message Queues vs Event Streams: Decoupling Asynchronous Systems\n\ndef solve():\n    \"\"\"\n    Verification: Design an end-to-end asynchronous order processing architecture comparing RabbitMQ task queues with \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "8.7", "subtopics_count": 6, "verification_criteria": "Design an end-to-end asynchronous order processing architecture comparing RabbitMQ task queues with Kafka event streaming.", "subtopics": ["8.7.1 Queue-based messaging (RabbitMQ, SQS): push model, message acknowledgment, individual message consumption, worker pools", "8.7.2 Log-based event streaming (Kafka, Kinesis): pull model, partitioned commit logs, ordered replayability, consumer groups", "8.7.3 Choosing between Queues and Streams: complex routing/task distribution vs high-throughput real-time event analytics", "8.7.4 Message delivery guarantees: At-most-once, At-least-once, Exactly-once processing (idempotent consumers)", "8.7.5 Dead Letter Queues (DLQ) and retry backoff strategies: handling poisoned messages without blocking queue pipelines", "8.7.6 Event-driven architecture patterns: Event Sourcing, Command Query Responsibility Segregation (CQRS), and Saga choreography"]}'::jsonb, '["Explain how this implementation prevents: Using a message queue as a permanent database without understanding broker storage limits and memory backpressure.", "How does Message Queues vs Event Streams: Decoupling Asynchronous Systems scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-8-8', 'phase-08-lesson-08-database-sharding-partitioning-rebalancin', 'module-9', 8, 'Lesson 9.8: Database Sharding, Partitioning & Rebalancing Strategies', 'Prerequisites: Phase 4, Phase 7', 'Prerequisites: Phase 4, Phase 7 | Subtopics: 6 items', 'Systems project application', 260, 9, 2120.0, 400.0, '# Lesson 8.8: Database Sharding, Partitioning & Rebalancing Strategies

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 4, Phase 7
- **Subtopics**:
  - `8.8.1` Vertical partitioning (splitting columns) vs Horizontal partitioning / Sharding (splitting rows across machines)
  - `8.8.2` Sharding key selection: cardinality, query access patterns, avoiding hot spots (celebrity problem)
  - `8.8.3` Sharding strategies: Range-based sharding vs Hash-based sharding vs Directory-based (lookup table) sharding
  - `8.8.4` Consistent Hashing in database sharding: minimizing data movement during node additions and removals
  - `8.8.5` Cross-shard queries and joins: scatter-gather queries, two-phase commit over shards, and why cross-shard joins are anti-patterns
  - `8.8.6` Live sharding rebalancing: migrating partitions online without downtime using dual-writes and asynchronous reconciliation
- **Key Failure Modes & Edge Cases**: Selecting a monotonically increasing auto-increment ID as sharding key, concentrating 100% of all write traffic on the latest single shard.
- **Verification & Mastery Check**: Implement a consistent hashing sharding manager in Python mapping keys across 16 database shards with virtual node balancing.
- **Project Application**: System Design Portfolio: Scalable database sharding architecture.', '{"solution.py": "# Phase 8 // Lesson 8.8: Database Sharding, Partitioning & Rebalancing Strategies\n\ndef solve():\n    \"\"\"\n    Verification: Implement a consistent hashing sharding manager in Python mapping keys across 16 database shards wit\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "8.8", "subtopics_count": 6, "verification_criteria": "Implement a consistent hashing sharding manager in Python mapping keys across 16 database shards with virtual node balancing.", "subtopics": ["8.8.1 Vertical partitioning (splitting columns) vs Horizontal partitioning / Sharding (splitting rows across machines)", "8.8.2 Sharding key selection: cardinality, query access patterns, avoiding hot spots (celebrity problem)", "8.8.3 Sharding strategies: Range-based sharding vs Hash-based sharding vs Directory-based (lookup table) sharding", "8.8.4 Consistent Hashing in database sharding: minimizing data movement during node additions and removals", "8.8.5 Cross-shard queries and joins: scatter-gather queries, two-phase commit over shards, and why cross-shard joins are anti-patterns", "8.8.6 Live sharding rebalancing: migrating partitions online without downtime using dual-writes and asynchronous reconciliation"]}'::jsonb, '["Explain how this implementation prevents: Selecting a monotonically increasing auto-increment ID as sharding key, concentrating 100% of all write traffic on the l", "How does Database Sharding, Partitioning & Rebalancing Strategies scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-8-9', 'phase-08-lesson-09-high-availability-redundancy-active-activ', 'module-9', 9, 'Lesson 9.9: High Availability, Redundancy & Active-Active Failover', 'Prerequisites: Phase 7, Lesson 8.8', 'Prerequisites: Phase 7, Lesson 8.8 | Subtopics: 6 items', 'Systems project application', 260, 9, 2000.0, 450.0, '# Lesson 8.9: High Availability, Redundancy & Active-Active Failover

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 7, Lesson 8.8
- **Subtopics**:
  - `8.9.1` High Availability (HA) metrics: 99.9% (Three Nines, 8.76h downtime/yr) vs 99.999% (Five Nines, 5.26m downtime/yr)
  - `8.9.2` Redundancy models: Active-Passive (Warm/Cold standby) vs Active-Active multi-region deployment architectures
  - `8.9.3` Automated failover mechanics: health heartbeats, split-brain detection, fencing tokens, and DNS TTL considerations
  - `8.9.4` Active-Active data synchronization: conflict-free replication, asynchronous cross-region replication, and multi-master conflicts
  - `8.9.5` GeoDNS and Latency-based Anycast routing: steering global users dynamically to healthy regions during catastrophic disasters
  - `8.9.6` Designing for disaster recovery: mean time to detect (MTTD), mean time to recover (MTTR), and chaos game days
- **Key Failure Modes & Edge Cases**: Split-brain condition causing two active masters in different datacenters to accept conflicting writes during network partition.
- **Verification & Mastery Check**: Draft an Active-Active multi-region architecture diagram with failover runbooks and split-brain fencing token safety proofs.
